class Street {
    #doors: number[];
    #cur_index: number = 0;

    constructor(doors: number[]) {
        this.#doors = doors;
    }

    public openDoor(): void {
        this.#doors[this.#cur_index] = 1;
    }

    public closeDoor(): void {
        this.#doors[this.#cur_index] = 0;
    }

    public isDoorOpen(): boolean {
        return this.#doors[this.#cur_index] !== 0;
    }

    public moveLeft(): void {
        this.#cur_index--;
        while (this.#cur_index < 0) {
            this.#cur_index += this.#doors.length;
        }
    }

    public moveRight(): void {
        this.#cur_index++;
        this.#cur_index %= this.#doors.length;
    }
}

